CREATE TABLE `food` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `category_id` bigint(20) NOT NULL COMMENT '分类ID',
  `code` varchar(255) DEFAULT NULL COMMENT '拼音编码',
  `name` varchar(255) DEFAULT NULL COMMENT '食物名称',
  `thumb_image_url` varchar(255) DEFAULT NULL COMMENT '食物图片',
  `is_liquid` int(11) DEFAULT NULL COMMENT '是否流食:0否;1是',
  `health_light` int(11) DEFAULT NULL COMMENT '健康灯:0未知;1绿灯;2黄灯;3红灯',
  `weight` varchar(50) DEFAULT NULL COMMENT '重量',
  `calory` varchar(50) DEFAULT NULL COMMENT '热量',
  `fat` varchar(50) DEFAULT NULL COMMENT '脂肪',
  `protein` varchar(50) DEFAULT NULL COMMENT '蛋白质',
  `fiber_dietary` varchar(50) DEFAULT NULL COMMENT '膳食纤维',
  `carbohydrate` varchar(50) DEFAULT NULL COMMENT '碳水化合物',
  `vitamin_a` varchar(50) DEFAULT NULL COMMENT '维生素A',
  `thiamine` varchar(50) DEFAULT NULL COMMENT '维生素B1',
  `lactoflavin` varchar(50) DEFAULT NULL COMMENT '维生素B2',
  `vitamin_c` varchar(50) DEFAULT NULL COMMENT '维生素C',
  `vitamin_e` varchar(50) DEFAULT NULL COMMENT '维生素E',
  `niacin` varchar(50) DEFAULT NULL COMMENT '烟酸',
  `natrium` varchar(50) DEFAULT NULL COMMENT '钠',
  `calcium` varchar(50) DEFAULT NULL COMMENT '钙',
  `iron` varchar(50) DEFAULT NULL COMMENT '铁',
  `kalium` varchar(50) DEFAULT NULL COMMENT '钾',
  `zinc` varchar(50) DEFAULT NULL COMMENT '锌',
  `selenium` varchar(50) DEFAULT NULL COMMENT '硒',
  `magnesium` varchar(50) DEFAULT NULL COMMENT '镁',
  `copper` varchar(50) DEFAULT NULL COMMENT '铜',
  `manganese` varchar(50) DEFAULT NULL COMMENT '锰',
  `cholesterol` varchar(50) DEFAULT NULL COMMENT '胆固醇',
  `folacin` varchar(50) DEFAULT NULL COMMENT '叶酸',
  `saturated_fat` varchar(50) DEFAULT NULL COMMENT '饱和脂肪',
  `sugar` varchar(50) DEFAULT NULL COMMENT '糖',
  `vitamin_b6` varchar(50) DEFAULT NULL COMMENT '维生素B6',
  `phosphor` varchar(50) DEFAULT NULL COMMENT '磷',
  `gi` varchar(50) DEFAULT NULL COMMENT '升糖指数',
  `gl` varchar(50) DEFAULT NULL COMMENT '升糖负荷',
  PRIMARY KEY (`id`),
  KEY `food_category_id_IDX` (`category_id`) USING BTREE,
  KEY `food_name_IDX` (`name`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=49690 DEFAULT CHARSET=utf8mb4 COMMENT='食物';

